def transform(grid):
    h, w = len(grid), len(grid[0])

    # The rectangle is the region of 1s, including its 1-valued border.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0 = min(r for r, c in ones)
    r1 = max(r for r, c in ones)
    c0 = min(c for r, c in ones)
    c1 = max(c for r, c in ones)
    a = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    ah, aw = len(a), len(a[0])

    outside = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if grid[r][c] != 0 and not (r0 <= r <= r1 and c0 <= c <= c1)
    ]
    if not outside:
        return a

    er0 = min(r for r, c, v in outside)
    er1 = max(r for r, c, v in outside)
    ec0 = min(c for r, c, v in outside)
    ec1 = max(c for r, c, v in outside)

    targets = {
        v: ((r - er0) / max(1, er1 - er0),
            (c - ec0) / max(1, ec1 - ec0))
        for r, c, v in outside
    }

    best_grid = a
    best_score = float("inf")

    # Transpose optionally, then independently flip rows and columns.
    for transpose in (False, True):
        for flip_rows in (False, True):
            for flip_cols in (False, True):
                oh, ow = (aw, ah) if transpose else (ah, aw)
                out = [[0] * ow for _ in range(oh)]

                def map_cell(r, c):
                    if transpose:
                        rr, cc = c, r
                    else:
                        rr, cc = r, c
                    if flip_rows:
                        rr = oh - 1 - rr
                    if flip_cols:
                        cc = ow - 1 - cc
                    return rr, cc

                for r in range(ah):
                    for c in range(aw):
                        rr, cc = map_cell(r, c)
                        out[rr][cc] = a[r][c]

                score = 0.0
                count = 0
                for _, _, color in outside:
                    positions = [
                        (r, c) for r in range(ah) for c in range(aw)
                        if a[r][c] == color
                    ]
                    if not positions or color not in targets:
                        continue
                    # These colors are the three reference markers in the panel.
                    r, c = positions[0]
                    rr, cc = map_cell(r, c)
                    actual = (rr / max(1, oh - 1), cc / max(1, ow - 1))
                    tr, tc = targets[color]
                    score += (actual[0] - tr) ** 2 + (actual[1] - tc) ** 2
                    count += 1

                if count and score < best_score:
                    best_score = score
                    best_grid = out

    return best_grid
